import React from 'react'
import { Routes, Route } from 'react-router-dom'
import MainLayout from '../components/MainLayout'
import ContentPage from '../components/contentPage/ContentPage'

// The whole app is a single layout with a catch-all content route. Each
// possible URL path is resolved at render time (see ContentPage) to the
// matching file inside /public/content, per the manifest generated by the
// Vite plugin. "/" is treated the same as "/readme".
export default function AppRouter() {
  return (
    <Routes>
      <Route element={<MainLayout />}>
        <Route path="/*" element={<ContentPage />} />
      </Route>
    </Routes>
  )
}
